    #include <bits/stdc++.h>
using namespace std;

vector<string> powerSet(string &s) {
    vector<string> ans = {""};

    for (char ch : s) {
        int size = ans.size();

        // Add current character to existing subsequences
        for (int i = 0; i < size; i++) {
            ans.push_back(ans[i] + ch);
        }
    }

    sort(ans.begin(), ans.end());
    return ans;
}

int main() {
    string s = "abc";

    vector<string> ans = powerSet(s);

    for (string str : ans)
        cout << str << " ";

    return 0;
}


