Output a ab abc ac b bc c Binary Representation - O(n × 2 ^ n) Time and O(n × 2 ^ n) SpaceThere are 2ⁿ possible subsequences, so consider every number from 0 to 2ⁿ - 1. Treat each number as a bitmaskA set bit means the corresponding character is included in the subsequence and an unset bit means it is skipped.For a string of length n, there are exactly 2ⁿ subsequences. Generate numbers from 0 to 2ⁿ - 1.  Consider each number as a binary representation.  Each bit corresponds to one character. Bit = 1 → include the character. Bit = 0 → skip the character. For "abc":000 → ""001 → "c"010 → "b"011 → "bc"100 → "a"101 → "ac"110 → "ab"111 → "abc"Thus, every possible combination of characters is generated
            C++

    #include <bits/stdc++.h>
using namespace std;

vector<string> powerSet(string &s) {
    int n = s.length();
    vector<string> ans;

    // Generate all possible bitmasks
    for (int mask = 0; mask < (1 << n); mask++) {
        string curr = "";

        // Check each bit
        for (int j = 0; j < n; j++) {
            if (mask & (1 << j))
                curr += s[j];
        }

        ans.push_back(curr);
    }

    sort(ans.begin(), ans.end());
    return ans;
}

int main() {
    string s = "abc";

    vector<string> ans = powerSet(s);

    for (string str : ans)
        cout << str << " ";

    return 0;
}


